Office.onReady(() => {
    // register a function named checkBeforeSend
    Office.actions.associate("checkBeforeSend", checkBeforeSend);
});

function checkBeforeSend(event) {
    const settings = getSettings();
    
    // すべてのチェックが無効の場合は送信を許可
    if (!settings.subjectCheck && !settings.recipientCheck && 
        !settings.attachmentCheck && !settings.keywordCheck && 
        !settings.externalDomainCheck) {
        event.completed({ allowEvent: true });
        return;
    }
    
    // メール情報を取得してチェック実行
    Office.context.mailbox.item.subject.getAsync((result) => {
        if (result.status === Office.AsyncResultStatus.Succeeded) {
            const subject = result.value || '';
            
            Office.context.mailbox.item.to.getAsync((toResult) => {
                if (toResult.status === Office.AsyncResultStatus.Succeeded) {
                    const recipients = toResult.value || [];
                    
                    Office.context.mailbox.item.body.getAsync(Office.CoercionType.Text, (bodyResult) => {
                        if (bodyResult.status === Office.AsyncResultStatus.Succeeded) {
                            const body = bodyResult.value || '';
                            
                            Office.context.mailbox.item.attachments.getAsync((attachResult) => {
                                if (attachResult.status === Office.AsyncResultStatus.Succeeded) {
                                    const attachments = attachResult.value || [];
                                    
                                    const issues = performChecks(subject, recipients, body, attachments, settings);
                                    
                                    if (issues.length > 0) {
                                        showConfirmationDialog(issues, event);
                                    } else {
                                        event.completed({ allowEvent: true });
                                    }
                                } else {
                                    event.completed({ allowEvent: true });
                                }
                            });
                        } else {
                            event.completed({ allowEvent: true });
                        }
                    });
                } else {
                    event.completed({ allowEvent: true });
                }
            });
        } else {
            event.completed({ allowEvent: true });
        }
    });
}

function performChecks(subject, recipients, body, attachments, settings) {
    const issues = [];
    
    // 件名チェック
    if (settings.subjectCheck && (!subject || subject.trim() === '')) {
        issues.push('件名が空です');
    }
    
    // 宛先チェック
    if (settings.recipientCheck && recipients.length === 0) {
        issues.push('宛先が設定されていません');
    }
    
    // 添付ファイルチェック
    if (settings.attachmentCheck) {
        const keywords = settings.attachmentKeywords.split(',').map(k => k.trim()).filter(k => k);
        const hasAttachmentKeyword = keywords.some(keyword => 
            subject.includes(keyword) || body.includes(keyword)
        );
        if (hasAttachmentKeyword && attachments.length === 0) {
            issues.push('添付ファイルに関するキーワードがありますが、ファイルが添付されていません');
        }
    }
    
    // キーワードチェック
    if (settings.keywordCheck) {
        const keywords = settings.warningKeywords.split(',').map(k => k.trim()).filter(k => k);
        const foundKeywords = keywords.filter(keyword => 
            subject.includes(keyword) || body.includes(keyword)
        );
        if (foundKeywords.length > 0) {
            issues.push('注意すべきキーワードが含まれています: ' + foundKeywords.join(', '));
        }
    }
    
    // 外部ドメインチェック
    if (settings.externalDomainCheck && settings.internalDomains) {
        const internalDomains = settings.internalDomains.split(',').map(d => d.trim()).filter(d => d);
        const externalRecipients = recipients.filter(recipient => {
            const email = recipient.emailAddress;
            return !internalDomains.some(domain => email.includes(domain));
        });
        if (externalRecipients.length > 0) {
            issues.push('外部ドメインへの送信が含まれています');
        }
    }
    
    return issues;
}

function showConfirmationDialog(issues, event) {
    const issueList = issues.map(issue => `<li>${issue}</li>`).join('');
    const dialogHtml = `
        <html>
        <head>
            <meta charset="UTF-8">
            <style>
                body {
                    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                    margin: 20px;
                    background-color: #fff;
                }
                .header {
                    color: #d13438;
                    font-size: 18px;
                    font-weight: bold;
                    margin-bottom: 15px;
                }
                .issues {
                    background-color: #fde7e9;
                    border: 1px solid #d13438;
                    border-radius: 4px;
                    padding: 15px;
                    margin-bottom: 20px;
                }
                ul {
                    margin: 10px 0;
                    padding-left: 20px;
                }
                li {
                    margin-bottom: 5px;
                }
                .button-container {
                    text-align: center;
                    margin-top: 20px;
                }
                button {
                    padding: 10px 20px;
                    margin: 0 10px;
                    border: none;
                    border-radius: 4px;
                    font-size: 14px;
                    cursor: pointer;
                }
                .send-btn {
                    background-color: #d13438;
                    color: white;
                }
                .cancel-btn {
                    background-color: #f3f2f1;
                    color: #323130;
                    border: 1px solid #d2d0ce;
                }
            </style>
        </head>
        <body>
            <div class="header">⚠ 誤送信チェック</div>
            <div class="issues">
                <strong>以下の問題が見つかりました:</strong>
                <ul>${issueList}</ul>
            </div>
            <p>それでも送信しますか？</p>
            <div class="button-container">
                <button class="send-btn" onclick="allowSend()">送信する</button>
                <button class="cancel-btn" onclick="cancelSend()">キャンセル</button>
            </div>
            <script>
                function allowSend() {
                    Office.context.ui.messageParent(JSON.stringify({ allowEvent: true }));
                }
                function cancelSend() {
                    Office.context.ui.messageParent(JSON.stringify({ allowEvent: false }));
                }
                Office.onReady(() => {
                    // Dialog is ready
                });
            </script>
        </body>
        </html>
    `;
    
    Office.context.ui.displayDialogAsync(
        `data:text/html,${encodeURIComponent(dialogHtml)}`,
        { height: 60, width: 50 },
        function(asyncResult) {
            if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
                const dialog = asyncResult.value;
                
                dialog.addEventHandler(Office.EventType.DialogMessageReceived, function(arg) {
                    try {
                        const response = JSON.parse(arg.message);
                        dialog.close();
                        event.completed(response);
                    } catch (error) {
                        dialog.close();
                        event.completed({ allowEvent: false });
                    }
                });
                
                dialog.addEventHandler(Office.EventType.DialogEventReceived, function(arg) {
                    dialog.close();
                    event.completed({ allowEvent: false });
                });
            } else {
                // ダイアログの表示に失敗した場合は送信を許可
                event.completed({ allowEvent: true });
            }
        }
    );
}

function getSettings() {
    try {
        const savedSettings = localStorage.getItem('emailCheckSettings');
        if (savedSettings) {
            return JSON.parse(savedSettings);
        }
    } catch (error) {
        console.error('設定の読み込みエラー:', error);
    }
    
    // デフォルト設定（すべて無効）
    return {
        subjectCheck: false,
        recipientCheck: false,
        attachmentCheck: false,
        keywordCheck: false,
        externalDomainCheck: false,
        attachmentKeywords: '添付,attachment,ファイル',
        warningKeywords: '機密,重要,urgent,極秘',
        internalDomains: ''
    };
}